import { useState } from "react";
import { Trash2, RotateCw, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { manualCacheClear, getCacheStats, printCacheStats } from "@/lib/cache-cleanup";

export function CacheCleanupPanel() {
  const [isClearing, setIsClearing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [cacheStats, setCacheStats] = useState(() => getCacheStats());

  const handleClearCache = async () => {
    setIsClearing(true);
    
    try {
      const result = manualCacheClear();
      
      if (result.success) {
        setShowSuccess(true);
        setCacheStats(getCacheStats());
        
        // Clear notification after 3 seconds
        setTimeout(() => setShowSuccess(false), 3000);
        
        // Suggest refresh
        setTimeout(() => {
          const shouldRefresh = window.confirm(
            "Cache cleared successfully. Refresh the page to load fresh data?"
          );
          if (shouldRefresh) {
            window.location.reload();
          }
        }, 500);
      }
    } catch (error) {
      console.error("Error clearing cache:", error);
    } finally {
      setIsClearing(false);
    }
  };

  const handleViewStats = () => {
    printCacheStats();
    console.log("📊 Cache statistics printed to console");
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Trash2 className="h-4 w-4" />
          Cache Management
        </CardTitle>
        <CardDescription>
          Manage cached data and improve website performance
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {showSuccess && (
          <Alert className="border-green-500/50 bg-green-50 dark:bg-green-950">
            <AlertCircle className="h-4 w-4 text-green-600 dark:text-green-400" />
            <AlertDescription className="text-green-800 dark:text-green-200">
              ✅ All caches cleared successfully! Page will refresh with fresh data.
            </AlertDescription>
          </Alert>
        )}

        <div className="space-y-2">
          <h4 className="font-medium text-sm">Cache Statistics</h4>
          <div className="grid grid-cols-2 gap-2 rounded-lg bg-muted/50 p-3">
            <div>
              <div className="text-xs text-muted-foreground">Total Size</div>
              <div className="font-mono text-sm font-semibold">
                {(cacheStats.totalSize / 1024).toFixed(2)} KB
              </div>
            </div>
            <div>
              <div className="text-xs text-muted-foreground">Cached Items</div>
              <div className="font-mono text-sm font-semibold">{cacheStats.itemCount}</div>
            </div>
          </div>
        </div>

        {cacheStats.itemCount > 0 && (
          <div className="space-y-2">
            <h4 className="font-medium text-sm">Cached Items</h4>
            <div className="space-y-1 rounded-lg bg-muted/50 p-3 text-xs">
              {cacheStats.items.map(({ key, size, age }) => (
                <div key={key} className="flex justify-between font-mono">
                  <span className="text-muted-foreground">{key}</span>
                  <span className="text-foreground">
                    {(size / 1024).toFixed(1)} KB {age && <span className="text-xs text-muted-foreground">({age})</span>}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        <Alert className="border-blue-500/50 bg-blue-50 dark:bg-blue-950">
          <AlertCircle className="h-4 w-4 text-blue-600 dark:text-blue-400" />
          <AlertDescription className="text-blue-800 dark:text-blue-200">
            Cache is automatically cleaned on each page load. Use "Clear All Cache" to manually force a complete cleanup.
          </AlertDescription>
        </Alert>

        <div className="flex gap-2">
          <Button
            onClick={handleClearCache}
            disabled={isClearing}
            variant="destructive"
            size="sm"
            className="gap-2"
          >
            {isClearing ? (
              <>
                <RotateCw className="h-4 w-4 animate-spin" />
                Clearing...
              </>
            ) : (
              <>
                <Trash2 className="h-4 w-4" />
                Clear All Cache
              </>
            )}
          </Button>

          <Button
            onClick={handleViewStats}
            variant="outline"
            size="sm"
            className="gap-2"
          >
            View in Console
          </Button>
        </div>

        <div className="rounded-lg border border-amber-500/50 bg-amber-50 p-3 text-xs dark:bg-amber-950">
          <p className="font-semibold text-amber-900 dark:text-amber-200 mb-1">💡 Tips:</p>
          <ul className="space-y-1 text-amber-800 dark:text-amber-200 list-disc list-inside">
            <li>Cache is automatically cleared when website version updates</li>
            <li>Stale data is automatically removed every hour</li>
            <li>Clear cache if you see outdated threat data</li>
            <li>View detailed cache stats in browser console (F12)</li>
            <li>Cache uses ~5-10 MB depending on active threats</li>
          </ul>
        </div>
      </CardContent>
    </Card>
  );
}
