import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { Building2, Globe, Cpu, Network, Bell, Save, Plus, X, Shield } from "lucide-react";

const INDUSTRIES = [
  "Technology","Finance / Banking","Healthcare","Government","Energy / Utilities",
  "Retail / E-Commerce","Manufacturing","Education","Legal","Media / Entertainment",
  "Telecom","Defense / Aerospace","Non-Profit","Other",
];

const EMPLOYEE_COUNTS = ["1-10","11-50","51-200","201-1000","1001-5000","5000+"];

interface OrgSettings {
  id?: string;
  org_id?: string;
  industry: string;
  employee_count: string;
  hq_country: string;
  company_domains: string[];
  internal_ips: string[];
  tech_keywords: string[];
  alert_threshold: string;
  min_confidence: number;
}

const DEFAULT: OrgSettings = {
  industry: "Technology",
  employee_count: "1-50",
  hq_country: "US",
  company_domains: [],
  internal_ips: [],
  tech_keywords: [],
  alert_threshold: "high",
  min_confidence: 60,
};

function TagInput({
  label, icon: Icon, values, onChange, placeholder,
}: {
  label: string;
  icon: React.ElementType;
  values: string[];
  onChange: (v: string[]) => void;
  placeholder: string;
}) {
  const [input, setInput] = useState("");
  const add = () => {
    const v = input.trim();
    if (v && !values.includes(v)) { onChange([...values, v]); setInput(""); }
  };
  return (
    <div>
      <Label className="text-xs text-slate-400 flex items-center gap-1.5 mb-1.5">
        <Icon className="h-3 w-3" />{label}
      </Label>
      <div className="flex gap-2 mb-2">
        <Input
          value={input}
          onChange={e => setInput(e.target.value)}
          placeholder={placeholder}
          className="h-8 text-xs"
          onKeyDown={e => e.key === "Enter" && (e.preventDefault(), add())}
        />
        <Button size="sm" variant="outline" className="h-8 px-2" onClick={add}>
          <Plus className="h-3.5 w-3.5" />
        </Button>
      </div>
      <div className="flex flex-wrap gap-1.5">
        {values.map(v => (
          <span key={v}
            className="flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full border"
            style={{ background: "rgba(6,182,212,0.1)", borderColor: "rgba(6,182,212,0.25)", color: "#22d3ee" }}
          >
            {v}
            <button onClick={() => onChange(values.filter(x => x !== v))} className="hover:text-red-400">
              <X className="h-2.5 w-2.5" />
            </button>
          </span>
        ))}
        {values.length === 0 && <span className="text-[10px] text-slate-600">None set — add some for better threat matching</span>}
      </div>
    </div>
  );
}

export function OrgProfilePanel() {
  const { toast } = useToast();
  const [settings, setSettings] = useState<OrgSettings>(DEFAULT);
  const [orgId, setOrgId] = useState<string>("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    async function load() {
      // Get default org
      const { data: orgs } = await supabase.from("organizations").select("id,name,slug").limit(1);
      if (!orgs || orgs.length === 0) { setLoading(false); return; }
      const org = orgs[0];
      setOrgId(org.id);

      const { data: s } = await supabase.from("org_settings").select("*").eq("org_id", org.id).maybeSingle();
      if (s) {
        setSettings({
          id: s.id,
          org_id: s.org_id,
          industry: s.industry ?? "Technology",
          employee_count: s.employee_count ?? "1-50",
          hq_country: s.hq_country ?? "US",
          company_domains: s.company_domains ?? [],
          internal_ips: s.internal_ips ?? [],
          tech_keywords: s.tech_keywords ?? [],
          alert_threshold: s.alert_threshold ?? "high",
          min_confidence: s.min_confidence ?? 60,
        });
      }
      setLoading(false);
    }
    load();
  }, []);

  async function save() {
    setSaving(true);
    const row = {
      org_id: orgId,
      industry: settings.industry,
      employee_count: settings.employee_count,
      hq_country: settings.hq_country,
      company_domains: settings.company_domains,
      internal_ips: settings.internal_ips,
      tech_keywords: settings.tech_keywords,
      alert_threshold: settings.alert_threshold,
      min_confidence: settings.min_confidence,
      updated_at: new Date().toISOString(),
    };
    const { error } = settings.id
      ? await supabase.from("org_settings").update(row).eq("id", settings.id)
      : await supabase.from("org_settings").insert([row]);
    setSaving(false);
    if (error) toast({ title: "Save failed", description: error.message, variant: "destructive" });
    else toast({ title: "Org profile saved", description: "Threat matching will now use your org context." });
  }

  if (loading) return <div className="py-8 text-center text-sm text-slate-500">Loading org profile…</div>;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3 p-4 rounded-xl"
        style={{ background: "linear-gradient(135deg, rgba(6,182,212,0.08), rgba(99,102,241,0.05))", border: "1px solid rgba(6,182,212,0.12)" }}>
        <div className="flex h-10 w-10 items-center justify-center rounded-xl"
          style={{ background: "rgba(6,182,212,0.15)", border: "1px solid rgba(6,182,212,0.3)" }}>
          <Building2 className="h-5 w-5 text-cyan-400" />
        </div>
        <div>
          <p className="text-sm font-semibold text-slate-200">Organization Profile</p>
          <p className="text-xs text-slate-500">Used for relevance scoring and asset-aware threat matching</p>
        </div>
        <div className="ml-auto flex items-center gap-1 text-[10px] text-emerald-400 bg-emerald-500/10 px-2 py-1 rounded-full border border-emerald-500/20">
          <Shield className="h-3 w-3" /> Context-Aware Intel
        </div>
      </div>

      {/* Basic info */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div>
          <Label className="text-xs text-slate-400 mb-1 block">Industry</Label>
          <Select value={settings.industry} onValueChange={v => setSettings(s => ({ ...s, industry: v }))}>
            <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
            <SelectContent>{INDUSTRIES.map(i => <SelectItem key={i} value={i} className="text-xs">{i}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div>
          <Label className="text-xs text-slate-400 mb-1 block">Company Size</Label>
          <Select value={settings.employee_count} onValueChange={v => setSettings(s => ({ ...s, employee_count: v }))}>
            <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
            <SelectContent>{EMPLOYEE_COUNTS.map(c => <SelectItem key={c} value={c} className="text-xs">{c} employees</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div>
          <Label className="text-xs text-slate-400 mb-1 block">HQ Country</Label>
          <Input value={settings.hq_country} onChange={e => setSettings(s => ({ ...s, hq_country: e.target.value }))}
            className="h-8 text-xs" placeholder="US" />
        </div>
      </div>

      {/* Alert thresholds */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div>
          <Label className="text-xs text-slate-400 flex items-center gap-1.5 mb-1.5">
            <Bell className="h-3 w-3" /> Minimum Alert Severity
          </Label>
          <Select value={settings.alert_threshold} onValueChange={v => setSettings(s => ({ ...s, alert_threshold: v }))}>
            <SelectTrigger className="h-8 text-xs"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="critical" className="text-xs">Critical only</SelectItem>
              <SelectItem value="high" className="text-xs">High and above</SelectItem>
              <SelectItem value="medium" className="text-xs">Medium and above</SelectItem>
              <SelectItem value="low" className="text-xs">All (low and above)</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div>
          <Label className="text-xs text-slate-400 mb-1.5 block">
            Minimum Confidence Score ({settings.min_confidence}%)
          </Label>
          <input type="range" min={0} max={100} step={5}
            value={settings.min_confidence}
            onChange={e => setSettings(s => ({ ...s, min_confidence: parseInt(e.target.value) }))}
            className="w-full accent-cyan-500"
          />
          <div className="flex justify-between text-[9px] text-slate-600 mt-0.5">
            <span>0% (all)</span><span>50%</span><span>100% (verified only)</span>
          </div>
        </div>
      </div>

      {/* Domain / IP / tech stack */}
      <div className="space-y-5 p-4 rounded-xl" style={{ background: "rgba(255,255,255,0.02)", border: "1px solid rgba(255,255,255,0.05)" }}>
        <TagInput
          label="Company Domains (for IOC matching)"
          icon={Globe}
          values={settings.company_domains}
          onChange={v => setSettings(s => ({ ...s, company_domains: v }))}
          placeholder="yourcompany.com"
        />
        <TagInput
          label="Internal IP Ranges (for asset correlation)"
          icon={Network}
          values={settings.internal_ips}
          onChange={v => setSettings(s => ({ ...s, internal_ips: v }))}
          placeholder="10.0.0.0/8"
        />
        <TagInput
          label="Tech Stack Keywords (improves relevance)"
          icon={Cpu}
          values={settings.tech_keywords}
          onChange={v => setSettings(s => ({ ...s, tech_keywords: v }))}
          placeholder="linux, nginx, aws, kubernetes"
        />
      </div>

      <div className="flex items-center gap-3 pt-2">
        <Button onClick={save} disabled={saving} className="gap-2"
          style={{ background: "linear-gradient(135deg,#06b6d4,#6366f1)", border: "none" }}>
          <Save className="h-4 w-4" />
          {saving ? "Saving…" : "Save Org Profile"}
        </Button>
        <p className="text-xs text-slate-600">
          These settings improve threat relevance scoring and asset matching across the platform.
        </p>
      </div>
    </div>
  );
}
